package com.example.kilgi.inventory.accounting;

public final class AccountingCatalog {

    public static final String CASH_CODE = "10100";
    public static final String CASH_NAME = "Cash / Mobile Wallet";
    public static final String INVENTORY_CODE = "12000";
    public static final String INVENTORY_NAME = "Merchandise Inventory - Vegetables";
    public static final String ACCOUNTS_PAYABLE_CODE = "20100";
    public static final String ACCOUNTS_PAYABLE_NAME = "Accounts Payable - Providers";
    public static final String COGS_CODE = "50100";
    public static final String COGS_NAME = "Cost of Goods Sold (COGS)";
    public static final String LOSS_CODE = "50200";
    public static final String LOSS_NAME = "Inventory Loss - Spoilage/Waste";

    private AccountingCatalog() {
    }
}

package com.example.kilgi.inventory.accounting;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;

import com.example.kilgi.inventory.data.JournalLineType;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class AccountingCatalog {

    public static final AccountingAccount CASH_IN_BANK = account(
            "10100",
            "Cash in Bank",
            AccountingAccount.Category.ASSET,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount ACCOUNTS_RECEIVABLE = account(
            "10300",
            "Accounts Receivable",
            AccountingAccount.Category.ASSET,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount OFFICE_EQUIPMENT = account(
            "11500",
            "Office Equipment",
            AccountingAccount.Category.ASSET,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount INVENTORY = account(
            "12000",
            "Merchandise Inventory - Vegetables",
            AccountingAccount.Category.ASSET,
            JournalLineType.DEBIT
    );

    public static final AccountingAccount ACCOUNTS_PAYABLE = account(
            "20100",
            "Accounts Payable",
            AccountingAccount.Category.LIABILITY,
            JournalLineType.CREDIT
    );
    public static final AccountingAccount NOTES_PAYABLE = account(
            "20200",
            "Notes Payable",
            AccountingAccount.Category.LIABILITY,
            JournalLineType.CREDIT
    );

    public static final AccountingAccount CAPITAL = account(
            "30100",
            "Capital",
            AccountingAccount.Category.OWNER_EQUITY,
            JournalLineType.CREDIT
    );
    public static final AccountingAccount DRAWING = account(
            "30200",
            "Drawing",
            AccountingAccount.Category.OWNER_EQUITY,
            JournalLineType.DEBIT
    );

    public static final AccountingAccount SALES = account(
            "40100",
            "Sales",
            AccountingAccount.Category.REVENUE,
            JournalLineType.CREDIT
    );
    public static final AccountingAccount SALES_DISCOUNT = account(
            "40200",
            "Sales Discount",
            AccountingAccount.Category.REVENUE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount SALES_RETURNS_AND_ALLOWANCES = account(
            "40300",
            "Sales Returns and Allowances",
            AccountingAccount.Category.REVENUE,
            JournalLineType.DEBIT
    );

    public static final AccountingAccount PURCHASES = account(
            "50100",
            "Purchases",
            AccountingAccount.Category.COST,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount FREIGHT_IN = account(
            "50200",
            "Freight-In",
            AccountingAccount.Category.COST,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount PURCHASE_DISCOUNT = account(
            "50300",
            "Purchase Discount",
            AccountingAccount.Category.COST,
            JournalLineType.CREDIT
    );
    public static final AccountingAccount PURCHASE_RETURNS_AND_ALLOWANCES = account(
            "50400",
            "Purchase Returns and Allowances",
            AccountingAccount.Category.COST,
            JournalLineType.CREDIT
    );
    public static final AccountingAccount COGS = account(
            "50500",
            "Cost of Goods Sold (COGS)",
            AccountingAccount.Category.COST,
            JournalLineType.DEBIT
    );

    public static final AccountingAccount TAXES_AND_LICENSES_EXPENSE = account(
            "60100",
            "Taxes and Licenses Expense",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount FREIGHT_OUT = account(
            "60200",
            "Freight-Out",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount RENT_EXPENSE = account(
            "60300",
            "Rent Expense",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount UTILITIES_EXPENSE = account(
            "60400",
            "Utilities Expense",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount ADVERTISING_EXPENSE = account(
            "60500",
            "Advertising Expense",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount SALARIES_EXPENSE = account(
            "60600",
            "Salaries Expense",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount SUPPLIES_EXPENSE = account(
            "60700",
            "Supplies Expense",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );
    public static final AccountingAccount INVENTORY_LOSS = account(
            "60800",
            "Inventory Loss - Spoilage/Waste",
            AccountingAccount.Category.EXPENSE,
            JournalLineType.DEBIT
    );

    public static final String CASH_CODE = CASH_IN_BANK.getCode();
    public static final String CASH_NAME = CASH_IN_BANK.getName();
    public static final String INVENTORY_CODE = INVENTORY.getCode();
    public static final String INVENTORY_NAME = INVENTORY.getName();
    public static final String ACCOUNTS_PAYABLE_CODE = ACCOUNTS_PAYABLE.getCode();
    public static final String ACCOUNTS_PAYABLE_NAME = ACCOUNTS_PAYABLE.getName();
    public static final String COGS_CODE = COGS.getCode();
    public static final String COGS_NAME = COGS.getName();
    public static final String LOSS_CODE = INVENTORY_LOSS.getCode();
    public static final String LOSS_NAME = INVENTORY_LOSS.getName();

    private static final List<AccountingAccount> ALL_ACCOUNTS = Collections.unmodifiableList(Arrays.asList(
            CASH_IN_BANK,
            ACCOUNTS_RECEIVABLE,
            OFFICE_EQUIPMENT,
            INVENTORY,
            ACCOUNTS_PAYABLE,
            NOTES_PAYABLE,
            CAPITAL,
            DRAWING,
            SALES,
            SALES_DISCOUNT,
            SALES_RETURNS_AND_ALLOWANCES,
            PURCHASES,
            FREIGHT_IN,
            PURCHASE_DISCOUNT,
            PURCHASE_RETURNS_AND_ALLOWANCES,
            COGS,
            TAXES_AND_LICENSES_EXPENSE,
            FREIGHT_OUT,
            RENT_EXPENSE,
            UTILITIES_EXPENSE,
            ADVERTISING_EXPENSE,
            SALARIES_EXPENSE,
            SUPPLIES_EXPENSE,
            INVENTORY_LOSS
    ));

    private static final Map<String, AccountingAccount> ACCOUNTS_BY_CODE = buildAccountsByCode();

    private AccountingCatalog() {
    }

    @NonNull
    public static List<AccountingAccount> getAllAccounts() {
        return ALL_ACCOUNTS;
    }

    @NonNull
    public static List<AccountingAccount> getAccountsByCategory(@NonNull AccountingAccount.Category category) {
        List<AccountingAccount> matches = new ArrayList<>();
        for (AccountingAccount account : ALL_ACCOUNTS) {
            if (account.getCategory() == category) {
                matches.add(account);
            }
        }
        return Collections.unmodifiableList(matches);
    }

    @Nullable
    public static AccountingAccount findByCode(String accountCode) {
        if (accountCode == null) {
            return null;
        }
        return ACCOUNTS_BY_CODE.get(accountCode.trim());
    }

    @NonNull
    public static AccountingAccount requireByCode(String accountCode) {
        AccountingAccount account = findByCode(accountCode);
        if (account == null) {
            throw new IllegalArgumentException("Unsupported account code: " + accountCode);
        }
        return account;
    }

    private static AccountingAccount account(
            String code,
            String name,
            AccountingAccount.Category category,
            JournalLineType normalBalance
    ) {
        return new AccountingAccount(code, name, category, normalBalance);
    }

    private static Map<String, AccountingAccount> buildAccountsByCode() {
        Map<String, AccountingAccount> accountsByCode = new LinkedHashMap<>();
        for (AccountingAccount account : ALL_ACCOUNTS) {
            accountsByCode.put(account.getCode(), account);
        }
        return Collections.unmodifiableMap(accountsByCode);
    }
}

package com.example.kilgi;

import android.content.Intent;
import android.os.Bundle;
import android.text.TextUtils;
import android.util.TypedValue;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.example.kilgi.inventory.data.JournalEntryWithLines;
import com.example.kilgi.inventory.data.JournalLineEntity;
import com.example.kilgi.inventory.data.JournalLineType;
import com.example.kilgi.inventory.data.KilgiDatabase;
import com.example.kilgi.inventory.data.LotWithDetails;
import com.example.kilgi.inventory.input.InventoryInputParser;
import com.example.kilgi.inventory.service.BatchValuationEngine;
import com.example.kilgi.inventory.service.BatchValuationSnapshot;
import com.example.kilgi.inventory.service.ModuleOneRepository;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.card.MaterialCardView;

import java.text.DateFormat;
import java.text.NumberFormat;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class JournalActivity extends AppCompatActivity {

    public static final String EXTRA_LOT_ID = "com.example.kilgi.extra.LOT_ID";

    private final NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(new Locale("en", "PH"));
    private final DateFormat dateTimeFormat = DateFormat.getDateTimeInstance(DateFormat.MEDIUM, DateFormat.SHORT, Locale.getDefault());
    private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();

    private MaterialToolbar topAppBar;
    private ScrollView contentScrollView;
    private EditText selectedLotIdInput;
    private TextView journalStatusView;
    private TextView journalLotSummaryView;
    private TextView journalEmptyStateView;
    private LinearLayout journalEntriesContainer;

    private ModuleOneRepository repository;
    private String initialLotId;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_journal);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        initialLotId = getIntent().getStringExtra(EXTRA_LOT_ID);
        repository = new ModuleOneRepository(KilgiDatabase.getInstance(this));
        bindViews();
        setupTopAppBar();
        bindActions();
        loadInitialJournal();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        ioExecutor.shutdown();
    }

    private void bindViews() {
        topAppBar = findViewById(R.id.top_app_bar);
        contentScrollView = findViewById(R.id.content_scroll);
        selectedLotIdInput = findViewById(R.id.edit_selected_lot_id);
        journalStatusView = findViewById(R.id.text_journal_status);
        journalLotSummaryView = findViewById(R.id.text_journal_lot_summary);
        journalEmptyStateView = findViewById(R.id.text_journal_empty_state);
        journalEntriesContainer = findViewById(R.id.layout_journal_entries);
    }

    private void setupTopAppBar() {
        topAppBar.setTitle(R.string.journal_screen_title);
        topAppBar.inflateMenu(R.menu.main_sections_menu);
        topAppBar.setOnMenuItemClickListener(item -> {
            if (item.getItemId() == R.id.menu_lot) {
                Intent intent = new Intent(this, MainActivity.class);
                String lotId = selectedLotIdInput.getText().toString().trim();
                if (!lotId.isEmpty()) {
                    intent.putExtra(EXTRA_LOT_ID, lotId);
                }
                intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT);
                startActivity(intent);
                return true;
            }
            if (item.getItemId() == R.id.menu_journal) {
                contentScrollView.post(() -> contentScrollView.smoothScrollTo(0, 0));
                return true;
            }
            return false;
        });
    }

    private void bindActions() {
        Button loadJournalButton = findViewById(R.id.button_load_journal);
        loadJournalButton.setOnClickListener(v -> loadSelectedJournal());
    }

    private void loadInitialJournal() {
        ioExecutor.execute(() -> refreshJournalOnWorker(initialLotId, null));
    }

    private void loadSelectedJournal() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            ioExecutor.execute(() -> refreshJournalOnWorker(
                    lotId,
                    getString(R.string.journal_status_loaded, lotId)
            ));
        } catch (IllegalArgumentException exception) {
            journalStatusView.setText(exception.getMessage());
        }
    }

    private void refreshJournalOnWorker(String requestedLotId, String statusMessage) {
        try {
            String effectiveLotId = requestedLotId;
            if (TextUtils.isEmpty(effectiveLotId)) {
                if (repository.getLatestLot() != null) {
                    effectiveLotId = repository.getLatestLot().lotId;
                }
            }

            String journalLotSummary = getString(R.string.journal_lot_summary_placeholder);
            List<JournalEntryWithLines> entries = null;
            if (!TextUtils.isEmpty(effectiveLotId)) {
                LotWithDetails lotWithDetails = repository.getLotWithDetails(effectiveLotId);
                BatchValuationSnapshot snapshot = BatchValuationEngine.calculate(
                        lotWithDetails.lot,
                        lotWithDetails.expenses,
                        lotWithDetails.spoilageLogs
                );
                journalLotSummary = buildJournalLotSummary(lotWithDetails, snapshot);
                entries = repository.getJournalEntries(effectiveLotId);
            }

            String finalEffectiveLotId = effectiveLotId;
            String finalJournalLotSummary = journalLotSummary;
            List<JournalEntryWithLines> finalEntries = entries;
            runOnUiThread(() -> {
                if (!TextUtils.isEmpty(finalEffectiveLotId)) {
                    selectedLotIdInput.setText(finalEffectiveLotId);
                }
                journalStatusView.setText(statusMessage == null
                        ? getString(R.string.journal_status_idle)
                        : statusMessage);
                journalLotSummaryView.setText(finalJournalLotSummary);
                renderJournalEntries(finalEntries);
            });
        } catch (Exception exception) {
            runOnUiThread(() -> {
                journalStatusView.setText(exception.getMessage());
                journalLotSummaryView.setText(R.string.journal_lot_summary_placeholder);
                renderJournalEntries(null);
            });
        }
    }

    private void renderJournalEntries(List<JournalEntryWithLines> entries) {
        journalEntriesContainer.removeAllViews();
        boolean hasEntries = entries != null && !entries.isEmpty();
        journalEmptyStateView.setVisibility(hasEntries ? View.GONE : View.VISIBLE);
        if (!hasEntries) {
            return;
        }

        for (int index = 0; index < entries.size(); index++) {
            journalEntriesContainer.addView(createJournalEntryCard(entries.get(index), index));
        }
    }

    private View createJournalEntryCard(JournalEntryWithLines entry, int index) {
        MaterialCardView cardView = new MaterialCardView(this);
        LinearLayout.LayoutParams cardParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        if (index > 0) {
            cardParams.topMargin = dp(12);
        }
        cardView.setLayoutParams(cardParams);
        cardView.setCardElevation(dp(1));
        cardView.setRadius(dp(16));
        cardView.setUseCompatPadding(true);

        LinearLayout content = new LinearLayout(this);
        content.setOrientation(LinearLayout.VERTICAL);
        content.setPadding(dp(16), dp(16), dp(16), dp(16));
        cardView.addView(content);

        TextView titleView = new TextView(this);
        titleView.setText(entry.entry.eventType);
        titleView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_TitleMedium);
        titleView.setTypeface(titleView.getTypeface(), android.graphics.Typeface.BOLD);
        content.addView(titleView);

        TextView descriptionView = new TextView(this);
        LinearLayout.LayoutParams descriptionParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        descriptionParams.topMargin = dp(4);
        descriptionView.setLayoutParams(descriptionParams);
        descriptionView.setText(entry.entry.description);
        descriptionView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyMedium);
        content.addView(descriptionView);

        TextView metaView = new TextView(this);
        LinearLayout.LayoutParams metaParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        metaParams.topMargin = dp(6);
        metaView.setLayoutParams(metaParams);
        metaView.setText(getString(
                R.string.journal_entry_meta,
                abbreviateLotId(entry.entry.lotId),
                dateTimeFormat.format(entry.entry.timestamp)
        ));
        metaView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodySmall);
        content.addView(metaView);

        LinearLayout linesContainer = new LinearLayout(this);
        LinearLayout.LayoutParams linesParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        linesParams.topMargin = dp(12);
        linesContainer.setLayoutParams(linesParams);
        linesContainer.setOrientation(LinearLayout.VERTICAL);
        content.addView(linesContainer);

        for (int lineIndex = 0; lineIndex < entry.lines.size(); lineIndex++) {
            linesContainer.addView(createJournalLineView(entry.lines.get(lineIndex), lineIndex));
        }

        return cardView;
    }

    private View createJournalLineView(JournalLineEntity line, int lineIndex) {
        LinearLayout lineLayout = new LinearLayout(this);
        lineLayout.setOrientation(LinearLayout.VERTICAL);
        if (lineIndex > 0) {
            LinearLayout.LayoutParams lineParams = new LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT
            );
            lineParams.topMargin = dp(10);
            lineLayout.setLayoutParams(lineParams);
        }

        LinearLayout topRow = new LinearLayout(this);
        topRow.setOrientation(LinearLayout.HORIZONTAL);
        topRow.setGravity(Gravity.CENTER_VERTICAL);
        lineLayout.addView(topRow);

        TextView sideView = new TextView(this);
        sideView.setText(JournalLineType.valueOf(line.lineType) == JournalLineType.DEBIT ? "DR" : "CR");
        sideView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_LabelLarge);
        sideView.setPadding(dp(10), dp(4), dp(10), dp(4));
        sideView.setBackgroundResource(android.R.drawable.dialog_holo_light_frame);
        topRow.addView(sideView);

        TextView accountView = new TextView(this);
        LinearLayout.LayoutParams accountParams = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        accountParams.leftMargin = dp(12);
        accountView.setLayoutParams(accountParams);
        accountView.setText(getString(R.string.journal_line_account, line.accountCode, line.accountName));
        accountView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyLarge);
        topRow.addView(accountView);

        TextView amountView = new TextView(this);
        amountView.setText(currencyFormat.format(line.amount));
        amountView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_TitleSmall);
        topRow.addView(amountView);

        String lineDetails = buildLineDetails(line);
        if (!lineDetails.isEmpty()) {
            TextView detailsView = new TextView(this);
            LinearLayout.LayoutParams detailsParams = new LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT
            );
            detailsParams.topMargin = dp(4);
            detailsView.setLayoutParams(detailsParams);
            detailsView.setText(lineDetails);
            detailsView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodySmall);
            lineLayout.addView(detailsView);
        }

        return lineLayout;
    }

    private String buildJournalLotSummary(LotWithDetails lotWithDetails, BatchValuationSnapshot snapshot) {
        return getString(
                R.string.journal_lot_summary,
                lotWithDetails.lot.vegetableType,
                lotWithDetails.lot.providerName,
                abbreviateLotId(lotWithDetails.lot.lotId),
                formatWeight(snapshot.getNetUsableKilograms()),
                currencyFormat.format(snapshot.getTotalCapitalizedCost())
        );
    }

    private String buildLineDetails(JournalLineEntity line) {
        StringBuilder builder = new StringBuilder();
        if (!TextUtils.isEmpty(line.memo)) {
            builder.append(line.memo.trim());
        }
        if (!TextUtils.isEmpty(line.paymentSource)) {
            appendSeparator(builder);
            builder.append(getString(R.string.journal_line_payment_source, line.paymentSource));
        }
        if (!TextUtils.isEmpty(line.providerId)) {
            appendSeparator(builder);
            builder.append(getString(R.string.journal_line_provider, line.providerId));
        }
        return builder.toString();
    }

    private void appendSeparator(StringBuilder builder) {
        if (builder.length() > 0) {
            builder.append(" • ");
        }
    }

    private String abbreviateLotId(String lotId) {
        if (TextUtils.isEmpty(lotId)) {
            return "-";
        }
        return lotId.length() <= 8 ? lotId : lotId.substring(0, 8);
    }

    private String formatWeight(double kilos) {
        return String.format(Locale.US, "%.2f kg", kilos);
    }

    private int dp(int value) {
        return (int) TypedValue.applyDimension(
                TypedValue.COMPLEX_UNIT_DIP,
                value,
                getResources().getDisplayMetrics()
        );
    }
}

package com.example.kilgi;

import android.content.Intent;
import android.os.Bundle;
import android.text.TextUtils;
import android.util.TypedValue;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.example.kilgi.inventory.accounting.AccountingAccount;
import com.example.kilgi.inventory.accounting.AccountingCatalog;
import com.example.kilgi.inventory.data.JournalEntryWithLines;
import com.example.kilgi.inventory.data.JournalLineEntity;
import com.example.kilgi.inventory.data.JournalLineType;
import com.example.kilgi.inventory.data.KilgiDatabase;
import com.example.kilgi.inventory.data.LotWithDetails;
import com.example.kilgi.inventory.input.InventoryInputParser;
import com.example.kilgi.inventory.service.BatchValuationEngine;
import com.example.kilgi.inventory.service.BatchValuationSnapshot;
import com.example.kilgi.inventory.service.ModuleOneRepository;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.card.MaterialCardView;

import java.text.DateFormat;
import java.text.NumberFormat;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class JournalActivity extends AppCompatActivity {

    public static final String EXTRA_LOT_ID = "com.example.kilgi.extra.LOT_ID";

    private final NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(new Locale("en", "PH"));
    private final DateFormat dateTimeFormat = DateFormat.getDateTimeInstance(DateFormat.MEDIUM, DateFormat.SHORT, Locale.getDefault());
    private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();

    private MaterialToolbar topAppBar;
    private ScrollView contentScrollView;
    private EditText selectedLotIdInput;
    private TextView journalStatusView;
    private TextView journalLotSummaryView;
    private TextView chartOfAccountsView;
    private TextView journalEmptyStateView;
    private LinearLayout journalEntriesContainer;

    private ModuleOneRepository repository;
    private String initialLotId;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_journal);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        initialLotId = getIntent().getStringExtra(EXTRA_LOT_ID);
        repository = new ModuleOneRepository(KilgiDatabase.getInstance(this));
        bindViews();
        chartOfAccountsView.setText(buildChartOfAccountsText());
        setupTopAppBar();
        bindActions();
        loadInitialJournal();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        ioExecutor.shutdown();
    }

    private void bindViews() {
        topAppBar = findViewById(R.id.top_app_bar);
        contentScrollView = findViewById(R.id.content_scroll);
        selectedLotIdInput = findViewById(R.id.edit_selected_lot_id);
        journalStatusView = findViewById(R.id.text_journal_status);
        journalLotSummaryView = findViewById(R.id.text_journal_lot_summary);
        chartOfAccountsView = findViewById(R.id.text_chart_of_accounts);
        journalEmptyStateView = findViewById(R.id.text_journal_empty_state);
        journalEntriesContainer = findViewById(R.id.layout_journal_entries);
    }

    private void setupTopAppBar() {
        topAppBar.setTitle(R.string.journal_screen_title);
        topAppBar.inflateMenu(R.menu.main_sections_menu);
        topAppBar.setOnMenuItemClickListener(item -> {
            if (item.getItemId() == R.id.menu_lot) {
                Intent intent = new Intent(this, MainActivity.class);
                String lotId = selectedLotIdInput.getText().toString().trim();
                if (!lotId.isEmpty()) {
                    intent.putExtra(EXTRA_LOT_ID, lotId);
                }
                intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT);
                startActivity(intent);
                return true;
            }
            if (item.getItemId() == R.id.menu_journal) {
                contentScrollView.post(() -> contentScrollView.smoothScrollTo(0, 0));
                return true;
            }
            return false;
        });
    }

    private void bindActions() {
        Button loadJournalButton = findViewById(R.id.button_load_journal);
        loadJournalButton.setOnClickListener(v -> loadSelectedJournal());
    }

    private void loadInitialJournal() {
        ioExecutor.execute(() -> refreshJournalOnWorker(initialLotId, null));
    }

    private void loadSelectedJournal() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            ioExecutor.execute(() -> refreshJournalOnWorker(
                    lotId,
                    getString(R.string.journal_status_loaded, lotId)
            ));
        } catch (IllegalArgumentException exception) {
            journalStatusView.setText(exception.getMessage());
        }
    }

    private void refreshJournalOnWorker(String requestedLotId, String statusMessage) {
        try {
            String effectiveLotId = requestedLotId;
            if (TextUtils.isEmpty(effectiveLotId)) {
                if (repository.getLatestLot() != null) {
                    effectiveLotId = repository.getLatestLot().lotId;
                }
            }

            String journalLotSummary = getString(R.string.journal_lot_summary_placeholder);
            List<JournalEntryWithLines> entries = null;
            if (!TextUtils.isEmpty(effectiveLotId)) {
                LotWithDetails lotWithDetails = repository.getLotWithDetails(effectiveLotId);
                BatchValuationSnapshot snapshot = BatchValuationEngine.calculate(
                        lotWithDetails.lot,
                        lotWithDetails.expenses,
                        lotWithDetails.spoilageLogs
                );
                journalLotSummary = buildJournalLotSummary(lotWithDetails, snapshot);
                entries = repository.getJournalEntries(effectiveLotId);
            }

            String finalEffectiveLotId = effectiveLotId;
            String finalJournalLotSummary = journalLotSummary;
            List<JournalEntryWithLines> finalEntries = entries;
            runOnUiThread(() -> {
                if (!TextUtils.isEmpty(finalEffectiveLotId)) {
                    selectedLotIdInput.setText(finalEffectiveLotId);
                }
                journalStatusView.setText(statusMessage == null
                        ? getString(R.string.journal_status_idle)
                        : statusMessage);
                journalLotSummaryView.setText(finalJournalLotSummary);
                renderJournalEntries(finalEntries);
            });
        } catch (Exception exception) {
            runOnUiThread(() -> {
                journalStatusView.setText(exception.getMessage());
                journalLotSummaryView.setText(R.string.journal_lot_summary_placeholder);
                renderJournalEntries(null);
            });
        }
    }

    private void renderJournalEntries(List<JournalEntryWithLines> entries) {
        journalEntriesContainer.removeAllViews();
        boolean hasEntries = entries != null && !entries.isEmpty();
        journalEmptyStateView.setVisibility(hasEntries ? View.GONE : View.VISIBLE);
        if (!hasEntries) {
            return;
        }

        for (int index = 0; index < entries.size(); index++) {
            journalEntriesContainer.addView(createJournalEntryCard(entries.get(index), index));
        }
    }

    private View createJournalEntryCard(JournalEntryWithLines entry, int index) {
        MaterialCardView cardView = new MaterialCardView(this);
        LinearLayout.LayoutParams cardParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        if (index > 0) {
            cardParams.topMargin = dp(12);
        }
        cardView.setLayoutParams(cardParams);
        cardView.setCardElevation(dp(1));
        cardView.setRadius(dp(16));
        cardView.setUseCompatPadding(true);

        LinearLayout content = new LinearLayout(this);
        content.setOrientation(LinearLayout.VERTICAL);
        content.setPadding(dp(16), dp(16), dp(16), dp(16));
        cardView.addView(content);

        TextView titleView = new TextView(this);
        titleView.setText(entry.entry.eventType);
        titleView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_TitleMedium);
        titleView.setTypeface(titleView.getTypeface(), android.graphics.Typeface.BOLD);
        content.addView(titleView);

        TextView descriptionView = new TextView(this);
        LinearLayout.LayoutParams descriptionParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        descriptionParams.topMargin = dp(4);
        descriptionView.setLayoutParams(descriptionParams);
        descriptionView.setText(entry.entry.description);
        descriptionView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyMedium);
        content.addView(descriptionView);

        TextView metaView = new TextView(this);
        LinearLayout.LayoutParams metaParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        metaParams.topMargin = dp(6);
        metaView.setLayoutParams(metaParams);
        metaView.setText(getString(
                R.string.journal_entry_meta,
                abbreviateLotId(entry.entry.lotId),
                dateTimeFormat.format(entry.entry.timestamp)
        ));
        metaView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodySmall);
        content.addView(metaView);

        LinearLayout linesContainer = new LinearLayout(this);
        LinearLayout.LayoutParams linesParams = new LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
        );
        linesParams.topMargin = dp(12);
        linesContainer.setLayoutParams(linesParams);
        linesContainer.setOrientation(LinearLayout.VERTICAL);
        content.addView(linesContainer);

        for (int lineIndex = 0; lineIndex < entry.lines.size(); lineIndex++) {
            linesContainer.addView(createJournalLineView(entry.lines.get(lineIndex), lineIndex));
        }

        return cardView;
    }

    private View createJournalLineView(JournalLineEntity line, int lineIndex) {
        LinearLayout lineLayout = new LinearLayout(this);
        lineLayout.setOrientation(LinearLayout.VERTICAL);
        if (lineIndex > 0) {
            LinearLayout.LayoutParams lineParams = new LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT
            );
            lineParams.topMargin = dp(10);
            lineLayout.setLayoutParams(lineParams);
        }

        LinearLayout topRow = new LinearLayout(this);
        topRow.setOrientation(LinearLayout.HORIZONTAL);
        topRow.setGravity(Gravity.CENTER_VERTICAL);
        lineLayout.addView(topRow);

        TextView sideView = new TextView(this);
        sideView.setText(JournalLineType.valueOf(line.lineType) == JournalLineType.DEBIT ? "DR" : "CR");
        sideView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_LabelLarge);
        sideView.setPadding(dp(10), dp(4), dp(10), dp(4));
        sideView.setBackgroundResource(android.R.drawable.dialog_holo_light_frame);
        topRow.addView(sideView);

        TextView accountView = new TextView(this);
        LinearLayout.LayoutParams accountParams = new LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f);
        accountParams.leftMargin = dp(12);
        accountView.setLayoutParams(accountParams);
        accountView.setText(getString(R.string.journal_line_account, line.accountCode, line.accountName));
        accountView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyLarge);
        topRow.addView(accountView);

        TextView amountView = new TextView(this);
        amountView.setText(currencyFormat.format(line.amount));
        amountView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_TitleSmall);
        topRow.addView(amountView);

        String lineDetails = buildLineDetails(line);
        if (!lineDetails.isEmpty()) {
            TextView detailsView = new TextView(this);
            LinearLayout.LayoutParams detailsParams = new LinearLayout.LayoutParams(
                    LinearLayout.LayoutParams.MATCH_PARENT,
                    LinearLayout.LayoutParams.WRAP_CONTENT
            );
            detailsParams.topMargin = dp(4);
            detailsView.setLayoutParams(detailsParams);
            detailsView.setText(lineDetails);
            detailsView.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodySmall);
            lineLayout.addView(detailsView);
        }

        return lineLayout;
    }

    private String buildJournalLotSummary(LotWithDetails lotWithDetails, BatchValuationSnapshot snapshot) {
        return getString(
                R.string.journal_lot_summary,
                lotWithDetails.lot.vegetableType,
                lotWithDetails.lot.providerName,
                abbreviateLotId(lotWithDetails.lot.lotId),
                formatWeight(snapshot.getNetUsableKilograms()),
                currencyFormat.format(snapshot.getTotalCapitalizedCost())
        );
    }

    private String buildLineDetails(JournalLineEntity line) {
        StringBuilder builder = new StringBuilder();
        if (!TextUtils.isEmpty(line.memo)) {
            builder.append(line.memo.trim());
        }
        if (!TextUtils.isEmpty(line.paymentSource)) {
            appendSeparator(builder);
            builder.append(getString(R.string.journal_line_payment_source, line.paymentSource));
        }
        if (!TextUtils.isEmpty(line.providerId)) {
            appendSeparator(builder);
            builder.append(getString(R.string.journal_line_provider, line.providerId));
        }
        return builder.toString();
    }

    private String buildChartOfAccountsText() {
        StringBuilder builder = new StringBuilder();
        for (AccountingAccount.Category category : AccountingAccount.Category.values()) {
            appendCategorySection(builder, category);
        }
        return builder.toString();
    }

    private void appendCategorySection(StringBuilder builder, AccountingAccount.Category category) {
        List<AccountingAccount> accounts = AccountingCatalog.getAccountsByCategory(category);
        if (accounts.isEmpty()) {
            return;
        }
        if (builder.length() > 0) {
            builder.append("\n\n");
        }
        builder.append(getString(R.string.journal_chart_category, category.getDisplayName()));
        for (AccountingAccount account : accounts) {
            builder.append("\n");
            builder.append(getString(
                    R.string.journal_chart_account_line,
                    account.getCode(),
                    account.getName(),
                    getNormalBalanceLabel(account.getNormalBalance())
            ));
        }
    }

    private String getNormalBalanceLabel(JournalLineType normalBalance) {
        return normalBalance == JournalLineType.DEBIT
                ? getString(R.string.journal_chart_normal_debit)
                : getString(R.string.journal_chart_normal_credit);
    }

    private void appendSeparator(StringBuilder builder) {
        if (builder.length() > 0) {
            builder.append(" • ");
        }
    }

    private String abbreviateLotId(String lotId) {
        if (TextUtils.isEmpty(lotId)) {
            return "-";
        }
        return lotId.length() <= 8 ? lotId : lotId.substring(0, 8);
    }

    private String formatWeight(double kilos) {
        return String.format(Locale.US, "%.2f kg", kilos);
    }

    private int dp(int value) {
        return (int) TypedValue.applyDimension(
                TypedValue.COMPLEX_UNIT_DIP,
                value,
                getResources().getDisplayMetrics()
        );
    }
}

package com.example.kilgi;

import android.os.Bundle;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Spinner;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.example.kilgi.inventory.data.JournalEntryWithLines;
import com.example.kilgi.inventory.data.JournalLineEntity;
import com.example.kilgi.inventory.data.JournalLineType;
import com.example.kilgi.inventory.data.KilgiDatabase;
import com.example.kilgi.inventory.data.LossType;
import com.example.kilgi.inventory.data.LotEntity;
import com.example.kilgi.inventory.data.LotWithDetails;
import com.example.kilgi.inventory.data.PaymentSource;
import com.example.kilgi.inventory.input.InventoryInputParser;
import com.example.kilgi.inventory.service.BatchValuationEngine;
import com.example.kilgi.inventory.service.BatchValuationSnapshot;
import com.example.kilgi.inventory.service.ModuleOneRepository;

import java.text.NumberFormat;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MainActivity extends AppCompatActivity {

    private final NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(new Locale("en", "PH"));
    private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();

    private EditText providerIdInput;
    private EditText providerNameInput;
    private EditText vegetableTypeInput;
    private EditText totalSacksInput;
    private EditText rawKilosInput;
    private EditText baseUnitPriceInput;
    private EditText standardFreightInput;
    private EditText selectedLotIdInput;
    private EditText expenseLabelInput;
    private EditText expenseAmountInput;
    private EditText spoilageKilosInput;
    private Spinner purchasePaymentSourceSpinner;
    private Spinner freightPaymentSourceSpinner;
    private Spinner expensePaymentSourceSpinner;
    private Spinner lossTypeSpinner;
    private TextView batchStatusView;
    private TextView expenseStatusView;
    private TextView spoilageStatusView;
    private TextView activeLotSummaryView;
    private TextView lotsOverviewView;
    private TextView journalSummaryView;

    private ModuleOneRepository repository;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        repository = new ModuleOneRepository(KilgiDatabase.getInstance(this));
        bindViews();
        setupSpinners();
        prefillSampleForm();
        bindActions();
        loadInitialDashboard();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        ioExecutor.shutdown();
    }

    private void bindViews() {
        providerIdInput = findViewById(R.id.edit_provider_id);
        providerNameInput = findViewById(R.id.edit_provider_name);
        vegetableTypeInput = findViewById(R.id.edit_vegetable_type);
        totalSacksInput = findViewById(R.id.edit_total_sacks);
        rawKilosInput = findViewById(R.id.edit_raw_kilos);
        baseUnitPriceInput = findViewById(R.id.edit_base_unit_price);
        standardFreightInput = findViewById(R.id.edit_standard_freight);
        selectedLotIdInput = findViewById(R.id.edit_selected_lot_id);
        expenseLabelInput = findViewById(R.id.edit_expense_label);
        expenseAmountInput = findViewById(R.id.edit_expense_amount);
        spoilageKilosInput = findViewById(R.id.edit_spoilage_kilos);
        purchasePaymentSourceSpinner = findViewById(R.id.spinner_purchase_payment_source);
        freightPaymentSourceSpinner = findViewById(R.id.spinner_freight_payment_source);
        expensePaymentSourceSpinner = findViewById(R.id.spinner_expense_payment_source);
        lossTypeSpinner = findViewById(R.id.spinner_loss_type);
        batchStatusView = findViewById(R.id.text_batch_status);
        expenseStatusView = findViewById(R.id.text_expense_status);
        spoilageStatusView = findViewById(R.id.text_spoilage_status);
        activeLotSummaryView = findViewById(R.id.text_active_lot_summary);
        lotsOverviewView = findViewById(R.id.text_all_lots_summary);
        journalSummaryView = findViewById(R.id.text_journal_summary);
    }

    private void setupSpinners() {
        ArrayAdapter<PaymentSource> paymentSourceAdapter = new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                PaymentSource.values()
        );
        paymentSourceAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        purchasePaymentSourceSpinner.setAdapter(paymentSourceAdapter);
        freightPaymentSourceSpinner.setAdapter(new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                PaymentSource.values()
        ));
        ((ArrayAdapter<?>) freightPaymentSourceSpinner.getAdapter())
                .setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        expensePaymentSourceSpinner.setAdapter(new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                PaymentSource.values()
        ));
        ((ArrayAdapter<?>) expensePaymentSourceSpinner.getAdapter())
                .setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);

        ArrayAdapter<LossType> lossTypeAdapter = new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                LossType.values()
        );
        lossTypeAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        lossTypeSpinner.setAdapter(lossTypeAdapter);

        purchasePaymentSourceSpinner.setSelection(PaymentSource.ACCOUNTS_PAYABLE.ordinal());
        freightPaymentSourceSpinner.setSelection(PaymentSource.CASH.ordinal());
        expensePaymentSourceSpinner.setSelection(PaymentSource.CASH.ordinal());
        lossTypeSpinner.setSelection(LossType.NORMAL.ordinal());
    }

    private void prefillSampleForm() {
        providerIdInput.setText("PROV-XYZ");
        providerNameInput.setText("Provider XYZ");
        vegetableTypeInput.setText("Tomatoes");
        totalSacksInput.setText("4");
        rawKilosInput.setText("100");
        baseUnitPriceInput.setText("1.50");
        standardFreightInput.setText("20");
        expenseLabelInput.setText("Market porter fee");
        expenseAmountInput.setText("10");
        spoilageKilosInput.setText("15");
    }

    private void bindActions() {
        Button createLotButton = findViewById(R.id.button_create_lot);
        Button refreshLotButton = findViewById(R.id.button_refresh_lot);
        Button addExpenseButton = findViewById(R.id.button_add_expense);
        Button logSpoilageButton = findViewById(R.id.button_log_spoilage);

        createLotButton.setOnClickListener(v -> createLot());
        refreshLotButton.setOnClickListener(v -> refreshSelectedLot());
        addExpenseButton.setOnClickListener(v -> addExpense());
        logSpoilageButton.setOnClickListener(v -> logSpoilage());
    }

    private void loadInitialDashboard() {
        ioExecutor.execute(() -> {
            LotEntity latestLot = repository.getLatestLot();
            String targetLotId = latestLot == null ? null : latestLot.lotId;
            refreshDashboardOnWorker(targetLotId, null, null, null);
        });
    }

    private void createLot() {
        try {
            String providerId = InventoryInputParser.requireText(providerIdInput.getText().toString(), "Provider ID");
            String providerName = InventoryInputParser.requireText(providerNameInput.getText().toString(), "Provider name");
            String vegetableType = InventoryInputParser.requireText(vegetableTypeInput.getText().toString(), "Vegetable type");
            int totalSacks = InventoryInputParser.parseRequiredPositiveInt(totalSacksInput.getText().toString(), "Total sacks purchased");
            double rawKilos = InventoryInputParser.parseRequiredPositiveDouble(rawKilosInput.getText().toString(), "Raw kilograms received");
            double baseUnitPrice = InventoryInputParser.parseOptionalNonNegativeDouble(baseUnitPriceInput.getText().toString(), "Base unit price per kilo");
            double standardFreight = InventoryInputParser.parseOptionalNonNegativeDouble(standardFreightInput.getText().toString(), "Standard freight");
            PaymentSource purchaseSource = (PaymentSource) purchasePaymentSourceSpinner.getSelectedItem();
            PaymentSource freightSource = (PaymentSource) freightPaymentSourceSpinner.getSelectedItem();

            ioExecutor.execute(() -> {
                try {
                    LotEntity lot = repository.createLot(
                            providerId,
                            providerName,
                            vegetableType,
                            totalSacks,
                            rawKilos,
                            baseUnitPrice,
                            purchaseSource,
                            standardFreight,
                            freightSource
                    );
                    refreshDashboardOnWorker(
                            lot.lotId,
                            getString(R.string.batch_created_message, lot.lotId),
                            getString(R.string.expense_status_idle),
                            getString(R.string.spoilage_status_idle)
                    );
                } catch (Exception exception) {
                    postStatuses(exception.getMessage(), null, null);
                }
            });
        } catch (IllegalArgumentException exception) {
            batchStatusView.setText(exception.getMessage());
        }
    }

    private void refreshSelectedLot() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            ioExecutor.execute(() -> refreshDashboardOnWorker(
                    lotId,
                    getString(R.string.batch_status_loaded, lotId),
                    null,
                    null
            ));
        } catch (IllegalArgumentException exception) {
            batchStatusView.setText(exception.getMessage());
        }
    }

    private void addExpense() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            String expenseLabel = InventoryInputParser.requireText(expenseLabelInput.getText().toString(), "Expense label");
            double amount = InventoryInputParser.parseRequiredPositiveDouble(expenseAmountInput.getText().toString(), "Expense amount");
            PaymentSource paymentSource = (PaymentSource) expensePaymentSourceSpinner.getSelectedItem();

            ioExecutor.execute(() -> {
                try {
                    repository.addExpense(lotId, expenseLabel, amount, paymentSource);
                    refreshDashboardOnWorker(
                            lotId,
                            null,
                            getString(R.string.expense_added_message, expenseLabel),
                            null
                    );
                } catch (Exception exception) {
                    postStatuses(null, exception.getMessage(), null);
                }
            });
        } catch (IllegalArgumentException exception) {
            expenseStatusView.setText(exception.getMessage());
        }
    }

    private void logSpoilage() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            double kilosLost = InventoryInputParser.parseRequiredPositiveDouble(spoilageKilosInput.getText().toString(), "Spoilage kilos");
            LossType lossType = (LossType) lossTypeSpinner.getSelectedItem();

            ioExecutor.execute(() -> {
                try {
                    repository.logSpoilage(lotId, kilosLost, lossType);
                    String message = lossType == LossType.NORMAL
                            ? getString(R.string.spoilage_logged_message, formatWeight(kilosLost))
                            : getString(R.string.abnormal_spoilage_logged_message, formatWeight(kilosLost));
                    refreshDashboardOnWorker(lotId, null, null, message);
                } catch (Exception exception) {
                    postStatuses(null, null, exception.getMessage());
                }
            });
        } catch (IllegalArgumentException exception) {
            spoilageStatusView.setText(exception.getMessage());
        }
    }

    private void refreshDashboardOnWorker(
            String targetLotId,
            String batchStatus,
            String expenseStatus,
            String spoilageStatus
    ) {
        try {
            List<LotEntity> allLots = repository.getAllLots();
            LotEntity latestLot = repository.getLatestLot();
            String effectiveLotId = targetLotId;
            if (effectiveLotId == null && latestLot != null) {
                effectiveLotId = latestLot.lotId;
            }

            String activeSummary = getString(R.string.no_active_lot_placeholder);
            String journalSummary = getString(R.string.no_journal_placeholder);
            if (effectiveLotId != null && !effectiveLotId.trim().isEmpty()) {
                LotWithDetails lotWithDetails = repository.getLotWithDetails(effectiveLotId);
                BatchValuationSnapshot snapshot = BatchValuationEngine.calculate(
                        lotWithDetails.lot,
                        lotWithDetails.expenses,
                        lotWithDetails.spoilageLogs
                );
                activeSummary = buildActiveLotSummary(lotWithDetails, snapshot);
                journalSummary = buildJournalSummary(repository.getJournalEntries(effectiveLotId));
            }

            String lotsOverview = buildLotsOverview(allLots);
            String finalEffectiveLotId = effectiveLotId;
            String finalActiveSummary = activeSummary;
            String finalJournalSummary = journalSummary;
            runOnUiThread(() -> {
                if (finalEffectiveLotId != null) {
                    selectedLotIdInput.setText(finalEffectiveLotId);
                }
                if (batchStatus != null) {
                    batchStatusView.setText(batchStatus);
                }
                if (expenseStatus != null) {
                    expenseStatusView.setText(expenseStatus);
                    expenseLabelInput.setText("");
                    expenseAmountInput.setText("");
                }
                if (spoilageStatus != null) {
                    spoilageStatusView.setText(spoilageStatus);
                    spoilageKilosInput.setText("");
                }
                activeLotSummaryView.setText(finalActiveSummary);
                lotsOverviewView.setText(lotsOverview);
                journalSummaryView.setText(finalJournalSummary);
            });
        } catch (Exception exception) {
            postStatuses(exception.getMessage(), exception.getMessage(), exception.getMessage());
        }
    }

    private void postStatuses(String batchStatus, String expenseStatus, String spoilageStatus) {
        runOnUiThread(() -> {
            if (batchStatus != null) {
                batchStatusView.setText(batchStatus);
            }
            if (expenseStatus != null) {
                expenseStatusView.setText(expenseStatus);
            }
            if (spoilageStatus != null) {
                spoilageStatusView.setText(spoilageStatus);
            }
        });
    }

    private String buildActiveLotSummary(LotWithDetails lotWithDetails, BatchValuationSnapshot snapshot) {
        LotEntity lot = lotWithDetails.lot;
        double additionalExpenseTotal = 0;
        for (int index = 0; index < lotWithDetails.expenses.size(); index++) {
            additionalExpenseTotal += lotWithDetails.expenses.get(index).amount;
        }
        StringBuilder builder = new StringBuilder();
        builder.append("Lot ID: ").append(lot.lotId)
                .append("\nProvider: ").append(lot.providerName).append(" (").append(lot.providerId).append(")")
                .append("\nVegetable: ").append(lot.vegetableType)
                .append("\nSacks purchased: ").append(lot.totalSacksPurchased)
                .append("\nRaw kilos received: ").append(formatWeight(lot.rawKilosReceived))
                .append("\nBase unit price: ").append(currencyFormat.format(lot.baseUnitPrice)).append(" / kg")
                .append("\nPurchase payment source: ").append(lot.purchasePaymentSource)
                .append("\nFreight payment source: ").append(lot.freightPaymentSource)
                .append("\nPurchase cost: ").append(currencyFormat.format(snapshot.getPurchaseCost()))
                .append("\nStandard freight: ").append(currencyFormat.format(lot.standardFreight))
                .append("\nAdditional expenses count: ").append(lotWithDetails.expenses.size())
                .append("\nAdditional expenses total: ").append(currencyFormat.format(additionalExpenseTotal))
                .append("\nNormal spoilage: ").append(formatWeight(snapshot.getNormalLossKilos()))
                .append("\nAbnormal spoilage: ").append(formatWeight(snapshot.getAbnormalLossKilos()))
                .append("\nAbnormal write-off value: ").append(currencyFormat.format(snapshot.getAbnormalWriteOffValue()))
                .append("\nTotal capitalized cost: ").append(currencyFormat.format(snapshot.getTotalCapitalizedCost()))
                .append("\nNet usable kilograms: ").append(formatWeight(snapshot.getNetUsableKilograms()))
                .append("\nTrue cost per kilo: ").append(formatCurrency(snapshot.getTrueCostPerKilo()));
        return builder.toString();
    }

    private String buildLotsOverview(List<LotEntity> lots) {
        if (lots == null || lots.isEmpty()) {
            return getString(R.string.no_lots_placeholder);
        }

        StringBuilder builder = new StringBuilder();
        for (LotEntity lot : lots) {
            try {
                LotWithDetails lotWithDetails = repository.getLotWithDetails(lot.lotId);
                BatchValuationSnapshot snapshot = BatchValuationEngine.calculate(
                        lotWithDetails.lot,
                        lotWithDetails.expenses,
                        lotWithDetails.spoilageLogs
                );
                builder.append("• ")
                        .append(lot.lotId, 0, Math.min(8, lot.lotId.length()))
                        .append(" | ")
                        .append(lot.vegetableType)
                        .append(" | usable ")
                        .append(formatWeight(snapshot.getNetUsableKilograms()))
                        .append(" | cap cost ")
                        .append(currencyFormat.format(snapshot.getTotalCapitalizedCost()))
                        .append("\n");
            } catch (Exception exception) {
                builder.append("• ").append(lot.lotId).append(" | ").append(exception.getMessage()).append("\n");
            }
        }
        return builder.toString().trim();
    }

    private String buildJournalSummary(List<JournalEntryWithLines> entries) {
        if (entries == null || entries.isEmpty()) {
            return getString(R.string.no_journal_placeholder);
        }

        StringBuilder builder = new StringBuilder();
        for (JournalEntryWithLines entry : entries) {
            builder.append(entry.entry.eventType)
                    .append(" - ")
                    .append(entry.entry.description)
                    .append("\n");
            for (JournalLineEntity line : entry.lines) {
                String prefix = JournalLineType.valueOf(line.lineType) == JournalLineType.DEBIT ? "DR" : "CR";
                builder.append("   ")
                        .append(prefix)
                        .append(" ")
                        .append(line.accountCode)
                        .append(" ")
                        .append(line.accountName)
                        .append(" | ")
                        .append(currencyFormat.format(line.amount));
                if (line.memo != null && !line.memo.trim().isEmpty()) {
                    builder.append(" | ").append(line.memo);
                }
                builder.append("\n");
            }
        }
        return builder.toString().trim();
    }

    private String formatWeight(double kilos) {
        return String.format(Locale.US, "%.2f kg", kilos);
    }

    private String formatCurrency(Double value) {
        if (value == null) {
            return getString(R.string.no_sellable_inventory);
        }
        return currencyFormat.format(value);
    }
}

package com.example.kilgi;

import android.os.Bundle;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ScrollView;
import android.widget.Spinner;
import android.widget.TextView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.google.android.material.appbar.MaterialToolbar;
import com.example.kilgi.inventory.data.JournalEntryWithLines;
import com.example.kilgi.inventory.data.JournalLineEntity;
import com.example.kilgi.inventory.data.JournalLineType;
import com.example.kilgi.inventory.data.KilgiDatabase;
import com.example.kilgi.inventory.data.LossType;
import com.example.kilgi.inventory.data.LotEntity;
import com.example.kilgi.inventory.data.LotWithDetails;
import com.example.kilgi.inventory.data.PaymentSource;
import com.example.kilgi.inventory.input.InventoryInputParser;
import com.example.kilgi.inventory.service.BatchValuationEngine;
import com.example.kilgi.inventory.service.BatchValuationSnapshot;
import com.example.kilgi.inventory.service.ModuleOneRepository;

import java.text.NumberFormat;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MainActivity extends AppCompatActivity {

    private final NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(new Locale("en", "PH"));
    private final ExecutorService ioExecutor = Executors.newSingleThreadExecutor();

    private MaterialToolbar topAppBar;
    private ScrollView contentScrollView;
    private EditText providerIdInput;
    private EditText providerNameInput;
    private EditText vegetableTypeInput;
    private EditText totalSacksInput;
    private EditText rawKilosInput;
    private EditText baseUnitPriceInput;
    private EditText standardFreightInput;
    private EditText selectedLotIdInput;
    private EditText expenseLabelInput;
    private EditText expenseAmountInput;
    private EditText spoilageKilosInput;
    private Spinner purchasePaymentSourceSpinner;
    private Spinner freightPaymentSourceSpinner;
    private Spinner expensePaymentSourceSpinner;
    private Spinner lossTypeSpinner;
    private TextView batchStatusView;
    private TextView expenseStatusView;
    private TextView spoilageStatusView;
    private TextView activeLotSummaryView;
    private TextView lotsOverviewView;
    private TextView journalSummaryView;
    private View lotSectionView;
    private View journalSectionView;

    private ModuleOneRepository repository;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        repository = new ModuleOneRepository(KilgiDatabase.getInstance(this));
        bindViews();
        setupTopAppBar();
        setupSpinners();
        prefillSampleForm();
        bindActions();
        loadInitialDashboard();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        ioExecutor.shutdown();
    }

    private void bindViews() {
        topAppBar = findViewById(R.id.top_app_bar);
        contentScrollView = findViewById(R.id.content_scroll);
        providerIdInput = findViewById(R.id.edit_provider_id);
        providerNameInput = findViewById(R.id.edit_provider_name);
        vegetableTypeInput = findViewById(R.id.edit_vegetable_type);
        totalSacksInput = findViewById(R.id.edit_total_sacks);
        rawKilosInput = findViewById(R.id.edit_raw_kilos);
        baseUnitPriceInput = findViewById(R.id.edit_base_unit_price);
        standardFreightInput = findViewById(R.id.edit_standard_freight);
        selectedLotIdInput = findViewById(R.id.edit_selected_lot_id);
        expenseLabelInput = findViewById(R.id.edit_expense_label);
        expenseAmountInput = findViewById(R.id.edit_expense_amount);
        spoilageKilosInput = findViewById(R.id.edit_spoilage_kilos);
        purchasePaymentSourceSpinner = findViewById(R.id.spinner_purchase_payment_source);
        freightPaymentSourceSpinner = findViewById(R.id.spinner_freight_payment_source);
        expensePaymentSourceSpinner = findViewById(R.id.spinner_expense_payment_source);
        lossTypeSpinner = findViewById(R.id.spinner_loss_type);
        batchStatusView = findViewById(R.id.text_batch_status);
        expenseStatusView = findViewById(R.id.text_expense_status);
        spoilageStatusView = findViewById(R.id.text_spoilage_status);
        activeLotSummaryView = findViewById(R.id.text_active_lot_summary);
        lotsOverviewView = findViewById(R.id.text_all_lots_summary);
        journalSummaryView = findViewById(R.id.text_journal_summary);
        lotSectionView = findViewById(R.id.section_lot);
        journalSectionView = findViewById(R.id.section_journal);
    }

    private void setupTopAppBar() {
        topAppBar.inflateMenu(R.menu.main_sections_menu);
        topAppBar.setOnMenuItemClickListener(item -> handleMenuNavigation(item.getItemId()));
    }

    private void setupSpinners() {
        ArrayAdapter<PaymentSource> paymentSourceAdapter = new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                PaymentSource.values()
        );
        paymentSourceAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        purchasePaymentSourceSpinner.setAdapter(paymentSourceAdapter);
        freightPaymentSourceSpinner.setAdapter(new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                PaymentSource.values()
        ));
        ((ArrayAdapter<?>) freightPaymentSourceSpinner.getAdapter())
                .setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        expensePaymentSourceSpinner.setAdapter(new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                PaymentSource.values()
        ));
        ((ArrayAdapter<?>) expensePaymentSourceSpinner.getAdapter())
                .setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);

        ArrayAdapter<LossType> lossTypeAdapter = new ArrayAdapter<>(
                this,
                android.R.layout.simple_spinner_item,
                LossType.values()
        );
        lossTypeAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        lossTypeSpinner.setAdapter(lossTypeAdapter);

        purchasePaymentSourceSpinner.setSelection(PaymentSource.ACCOUNTS_PAYABLE.ordinal());
        freightPaymentSourceSpinner.setSelection(PaymentSource.CASH.ordinal());
        expensePaymentSourceSpinner.setSelection(PaymentSource.CASH.ordinal());
        lossTypeSpinner.setSelection(LossType.NORMAL.ordinal());
    }

    private void prefillSampleForm() {
        providerIdInput.setText("PROV-XYZ");
        providerNameInput.setText("Provider XYZ");
        vegetableTypeInput.setText("Tomatoes");
        totalSacksInput.setText("4");
        rawKilosInput.setText("100");
        baseUnitPriceInput.setText("1.50");
        standardFreightInput.setText("20");
        expenseLabelInput.setText("Market porter fee");
        expenseAmountInput.setText("10");
        spoilageKilosInput.setText("15");
    }

    private void bindActions() {
        Button createLotButton = findViewById(R.id.button_create_lot);
        Button refreshLotButton = findViewById(R.id.button_refresh_lot);
        Button addExpenseButton = findViewById(R.id.button_add_expense);
        Button logSpoilageButton = findViewById(R.id.button_log_spoilage);

        createLotButton.setOnClickListener(v -> createLot());
        refreshLotButton.setOnClickListener(v -> refreshSelectedLot());
        addExpenseButton.setOnClickListener(v -> addExpense());
        logSpoilageButton.setOnClickListener(v -> logSpoilage());
    }

    private boolean handleMenuNavigation(int itemId) {
        if (itemId == R.id.menu_lot) {
            scrollToSection(lotSectionView);
            return true;
        }
        if (itemId == R.id.menu_journal) {
            scrollToSection(journalSectionView);
            return true;
        }
        return false;
    }

    private void scrollToSection(View sectionView) {
        if (sectionView == null || contentScrollView == null) {
            return;
        }
        contentScrollView.post(() -> contentScrollView.smoothScrollTo(0, sectionView.getTop()));
    }

    private void loadInitialDashboard() {
        ioExecutor.execute(() -> {
            LotEntity latestLot = repository.getLatestLot();
            String targetLotId = latestLot == null ? null : latestLot.lotId;
            refreshDashboardOnWorker(targetLotId, null, null, null);
        });
    }

    private void createLot() {
        try {
            String providerId = InventoryInputParser.requireText(providerIdInput.getText().toString(), "Provider ID");
            String providerName = InventoryInputParser.requireText(providerNameInput.getText().toString(), "Provider name");
            String vegetableType = InventoryInputParser.requireText(vegetableTypeInput.getText().toString(), "Vegetable type");
            int totalSacks = InventoryInputParser.parseRequiredPositiveInt(totalSacksInput.getText().toString(), "Total sacks purchased");
            double rawKilos = InventoryInputParser.parseRequiredPositiveDouble(rawKilosInput.getText().toString(), "Raw kilograms received");
            double baseUnitPrice = InventoryInputParser.parseOptionalNonNegativeDouble(baseUnitPriceInput.getText().toString(), "Base unit price per kilo");
            double standardFreight = InventoryInputParser.parseOptionalNonNegativeDouble(standardFreightInput.getText().toString(), "Standard freight");
            PaymentSource purchaseSource = (PaymentSource) purchasePaymentSourceSpinner.getSelectedItem();
            PaymentSource freightSource = (PaymentSource) freightPaymentSourceSpinner.getSelectedItem();

            ioExecutor.execute(() -> {
                try {
                    LotEntity lot = repository.createLot(
                            providerId,
                            providerName,
                            vegetableType,
                            totalSacks,
                            rawKilos,
                            baseUnitPrice,
                            purchaseSource,
                            standardFreight,
                            freightSource
                    );
                    refreshDashboardOnWorker(
                            lot.lotId,
                            getString(R.string.batch_created_message, lot.lotId),
                            getString(R.string.expense_status_idle),
                            getString(R.string.spoilage_status_idle)
                    );
                } catch (Exception exception) {
                    postStatuses(exception.getMessage(), null, null);
                }
            });
        } catch (IllegalArgumentException exception) {
            batchStatusView.setText(exception.getMessage());
        }
    }

    private void refreshSelectedLot() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            ioExecutor.execute(() -> refreshDashboardOnWorker(
                    lotId,
                    getString(R.string.batch_status_loaded, lotId),
                    null,
                    null
            ));
        } catch (IllegalArgumentException exception) {
            batchStatusView.setText(exception.getMessage());
        }
    }

    private void addExpense() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            String expenseLabel = InventoryInputParser.requireText(expenseLabelInput.getText().toString(), "Expense label");
            double amount = InventoryInputParser.parseRequiredPositiveDouble(expenseAmountInput.getText().toString(), "Expense amount");
            PaymentSource paymentSource = (PaymentSource) expensePaymentSourceSpinner.getSelectedItem();

            ioExecutor.execute(() -> {
                try {
                    repository.addExpense(lotId, expenseLabel, amount, paymentSource);
                    refreshDashboardOnWorker(
                            lotId,
                            null,
                            getString(R.string.expense_added_message, expenseLabel),
                            null
                    );
                } catch (Exception exception) {
                    postStatuses(null, exception.getMessage(), null);
                }
            });
        } catch (IllegalArgumentException exception) {
            expenseStatusView.setText(exception.getMessage());
        }
    }

    private void logSpoilage() {
        try {
            String lotId = InventoryInputParser.requireText(selectedLotIdInput.getText().toString(), "Selected lot ID");
            double kilosLost = InventoryInputParser.parseRequiredPositiveDouble(spoilageKilosInput.getText().toString(), "Spoilage kilos");
            LossType lossType = (LossType) lossTypeSpinner.getSelectedItem();

            ioExecutor.execute(() -> {
                try {
                    repository.logSpoilage(lotId, kilosLost, lossType);
                    String message = lossType == LossType.NORMAL
                            ? getString(R.string.spoilage_logged_message, formatWeight(kilosLost))
                            : getString(R.string.abnormal_spoilage_logged_message, formatWeight(kilosLost));
                    refreshDashboardOnWorker(lotId, null, null, message);
                } catch (Exception exception) {
                    postStatuses(null, null, exception.getMessage());
                }
            });
        } catch (IllegalArgumentException exception) {
            spoilageStatusView.setText(exception.getMessage());
        }
    }

    private void refreshDashboardOnWorker(
            String targetLotId,
            String batchStatus,
            String expenseStatus,
            String spoilageStatus
    ) {
        try {
            List<LotEntity> allLots = repository.getAllLots();
            LotEntity latestLot = repository.getLatestLot();
            String effectiveLotId = targetLotId;
            if (effectiveLotId == null && latestLot != null) {
                effectiveLotId = latestLot.lotId;
            }

            String activeSummary = getString(R.string.no_active_lot_placeholder);
            String journalSummary = getString(R.string.no_journal_placeholder);
            if (effectiveLotId != null && !effectiveLotId.trim().isEmpty()) {
                LotWithDetails lotWithDetails = repository.getLotWithDetails(effectiveLotId);
                BatchValuationSnapshot snapshot = BatchValuationEngine.calculate(
                        lotWithDetails.lot,
                        lotWithDetails.expenses,
                        lotWithDetails.spoilageLogs
                );
                activeSummary = buildActiveLotSummary(lotWithDetails, snapshot);
                journalSummary = buildJournalSummary(repository.getJournalEntries(effectiveLotId));
            }

            String lotsOverview = buildLotsOverview(allLots);
            String finalEffectiveLotId = effectiveLotId;
            String finalActiveSummary = activeSummary;
            String finalJournalSummary = journalSummary;
            runOnUiThread(() -> {
                if (finalEffectiveLotId != null) {
                    selectedLotIdInput.setText(finalEffectiveLotId);
                }
                if (batchStatus != null) {
                    batchStatusView.setText(batchStatus);
                }
                if (expenseStatus != null) {
                    expenseStatusView.setText(expenseStatus);
                    expenseLabelInput.setText("");
                    expenseAmountInput.setText("");
                }
                if (spoilageStatus != null) {
                    spoilageStatusView.setText(spoilageStatus);
                    spoilageKilosInput.setText("");
                }
                activeLotSummaryView.setText(finalActiveSummary);
                lotsOverviewView.setText(lotsOverview);
                journalSummaryView.setText(finalJournalSummary);
            });
        } catch (Exception exception) {
            postStatuses(exception.getMessage(), exception.getMessage(), exception.getMessage());
        }
    }

    private void postStatuses(String batchStatus, String expenseStatus, String spoilageStatus) {
        runOnUiThread(() -> {
            if (batchStatus != null) {
                batchStatusView.setText(batchStatus);
            }
            if (expenseStatus != null) {
                expenseStatusView.setText(expenseStatus);
            }
            if (spoilageStatus != null) {
                spoilageStatusView.setText(spoilageStatus);
            }
        });
    }

    private String buildActiveLotSummary(LotWithDetails lotWithDetails, BatchValuationSnapshot snapshot) {
        LotEntity lot = lotWithDetails.lot;
        double additionalExpenseTotal = 0;
        for (int index = 0; index < lotWithDetails.expenses.size(); index++) {
            additionalExpenseTotal += lotWithDetails.expenses.get(index).amount;
        }
        StringBuilder builder = new StringBuilder();
        builder.append("Lot ID: ").append(lot.lotId)
                .append("\nProvider: ").append(lot.providerName).append(" (").append(lot.providerId).append(")")
                .append("\nVegetable: ").append(lot.vegetableType)
                .append("\nSacks purchased: ").append(lot.totalSacksPurchased)
                .append("\nRaw kilos received: ").append(formatWeight(lot.rawKilosReceived))
                .append("\nBase unit price: ").append(currencyFormat.format(lot.baseUnitPrice)).append(" / kg")
                .append("\nPurchase payment source: ").append(lot.purchasePaymentSource)
                .append("\nFreight payment source: ").append(lot.freightPaymentSource)
                .append("\nPurchase cost: ").append(currencyFormat.format(snapshot.getPurchaseCost()))
                .append("\nStandard freight: ").append(currencyFormat.format(lot.standardFreight))
                .append("\nAdditional expenses count: ").append(lotWithDetails.expenses.size())
                .append("\nAdditional expenses total: ").append(currencyFormat.format(additionalExpenseTotal))
                .append("\nNormal spoilage: ").append(formatWeight(snapshot.getNormalLossKilos()))
                .append("\nAbnormal spoilage: ").append(formatWeight(snapshot.getAbnormalLossKilos()))
                .append("\nAbnormal write-off value: ").append(currencyFormat.format(snapshot.getAbnormalWriteOffValue()))
                .append("\nTotal capitalized cost: ").append(currencyFormat.format(snapshot.getTotalCapitalizedCost()))
                .append("\nNet usable kilograms: ").append(formatWeight(snapshot.getNetUsableKilograms()))
                .append("\nTrue cost per kilo: ").append(formatCurrency(snapshot.getTrueCostPerKilo()));
        return builder.toString();
    }

    private String buildLotsOverview(List<LotEntity> lots) {
        if (lots == null || lots.isEmpty()) {
            return getString(R.string.no_lots_placeholder);
        }

        StringBuilder builder = new StringBuilder();
        for (LotEntity lot : lots) {
            try {
                LotWithDetails lotWithDetails = repository.getLotWithDetails(lot.lotId);
                BatchValuationSnapshot snapshot = BatchValuationEngine.calculate(
                        lotWithDetails.lot,
                        lotWithDetails.expenses,
                        lotWithDetails.spoilageLogs
                );
                builder.append("• ")
                        .append(lot.lotId, 0, Math.min(8, lot.lotId.length()))
                        .append(" | ")
                        .append(lot.vegetableType)
                        .append(" | usable ")
                        .append(formatWeight(snapshot.getNetUsableKilograms()))
                        .append(" | cap cost ")
                        .append(currencyFormat.format(snapshot.getTotalCapitalizedCost()))
                        .append("\n");
            } catch (Exception exception) {
                builder.append("• ").append(lot.lotId).append(" | ").append(exception.getMessage()).append("\n");
            }
        }
        return builder.toString().trim();
    }

    private String buildJournalSummary(List<JournalEntryWithLines> entries) {
        if (entries == null || entries.isEmpty()) {
            return getString(R.string.no_journal_placeholder);
        }

        StringBuilder builder = new StringBuilder();
        for (JournalEntryWithLines entry : entries) {
            builder.append(entry.entry.eventType)
                    .append(" - ")
                    .append(entry.entry.description)
                    .append("\n");
            for (JournalLineEntity line : entry.lines) {
                String prefix = JournalLineType.valueOf(line.lineType) == JournalLineType.DEBIT ? "DR" : "CR";
                builder.append("   ")
                        .append(prefix)
                        .append(" ")
                        .append(line.accountCode)
                        .append(" ")
                        .append(line.accountName)
                        .append(" | ")
                        .append(currencyFormat.format(line.amount));
                if (line.memo != null && !line.memo.trim().isEmpty()) {
                    builder.append(" | ").append(line.memo);
                }
                builder.append("\n");
            }
        }
        return builder.toString().trim();
    }

    private String formatWeight(double kilos) {
        return String.format(Locale.US, "%.2f kg", kilos);
    }

    private String formatCurrency(Double value) {
        if (value == null) {
            return getString(R.string.no_sellable_inventory);
        }
        return currencyFormat.format(value);
    }
}

package com.example.kilgi.inventory.data;

/**
 * Source account used to settle a procurement-related obligation.
 */
public enum PaymentSource {
    CASH("CASH", "10100", "Cash / Mobile Wallet"),
    ACCOUNTS_PAYABLE("AP", "20100", "Accounts Payable - Providers");

    private final String storedValue;
    private final String accountCode;
    private final String accountName;

    PaymentSource(String storedValue, String accountCode, String accountName) {
        this.storedValue = storedValue;
        this.accountCode = accountCode;
        this.accountName = accountName;
    }

    public String getStoredValue() {
        return storedValue;
    }

    public String getAccountCode() {
        return accountCode;
    }

    public String getAccountName() {
        return accountName;
    }

    public static PaymentSource fromStoredValue(String value) {
        for (PaymentSource source : values()) {
            if (source.storedValue.equalsIgnoreCase(value)) {
                return source;
            }
        }
        throw new IllegalArgumentException("Unsupported payment source: " + value);
    }

    @Override
    public String toString() {
        return storedValue;
    }
}

package com.example.kilgi.inventory.data;

import com.example.kilgi.inventory.accounting.AccountingCatalog;

/**
 * Source account used to settle a procurement-related obligation.
 */
public enum PaymentSource {
    CASH("CASH", AccountingCatalog.CASH_CODE, AccountingCatalog.CASH_NAME),
    ACCOUNTS_PAYABLE("AP", AccountingCatalog.ACCOUNTS_PAYABLE_CODE, AccountingCatalog.ACCOUNTS_PAYABLE_NAME);

    private final String storedValue;
    private final String accountCode;
    private final String accountName;

    PaymentSource(String storedValue, String accountCode, String accountName) {
        this.storedValue = storedValue;
        this.accountCode = accountCode;
        this.accountName = accountName;
    }

    public String getStoredValue() {
        return storedValue;
    }

    public String getAccountCode() {
        return accountCode;
    }

    public String getAccountName() {
        return accountName;
    }

    public static PaymentSource fromStoredValue(String value) {
        for (PaymentSource source : values()) {
            if (source.storedValue.equalsIgnoreCase(value)) {
                return source;
            }
        }
        throw new IllegalArgumentException("Unsupported payment source: " + value);
    }

    @Override
    public String toString() {
        return storedValue;
    }
}

package com.example.kilgi.inventory.model;

import com.example.kilgi.inventory.engine.LandedCostCalculator;
import com.example.kilgi.inventory.engine.TrueCostPerKiloEngine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Core domain model for a vegetable procurement batch.
 */
public class ProcurementBatch {

    private final String productName;
    private final String providerName;
    private final double purchasedUnitCount;
    private final UnitConversion unitConversion;
    private final double baseItemPrice;
    private final double shippingFees;
    private final double storeDeliveryFees;
    private final double rawSortingLaborCost;
    private final double packagingMaterialCost;
    private final List<SpoilageEntry> spoilageEntries = new ArrayList<>();

    public ProcurementBatch(
            String productName,
            String providerName,
            double purchasedUnitCount,
            UnitConversion unitConversion,
            double baseItemPrice,
            double shippingFees,
            double storeDeliveryFees,
            double rawSortingLaborCost,
            double packagingMaterialCost
    ) {
        this.productName = requireText(productName, "productName");
        this.providerName = requireText(providerName, "providerName");
        if (purchasedUnitCount <= 0) {
            throw new IllegalArgumentException("purchasedUnitCount must be greater than zero.");
        }
        if (unitConversion == null) {
            throw new IllegalArgumentException("unitConversion cannot be null.");
        }
        validateNonNegative(baseItemPrice, "baseItemPrice");
        validateNonNegative(shippingFees, "shippingFees");
        validateNonNegative(storeDeliveryFees, "storeDeliveryFees");
        validateNonNegative(rawSortingLaborCost, "rawSortingLaborCost");
        validateNonNegative(packagingMaterialCost, "packagingMaterialCost");

        this.purchasedUnitCount = purchasedUnitCount;
        this.unitConversion = unitConversion;
        this.baseItemPrice = baseItemPrice;
        this.shippingFees = shippingFees;
        this.storeDeliveryFees = storeDeliveryFees;
        this.rawSortingLaborCost = rawSortingLaborCost;
        this.packagingMaterialCost = packagingMaterialCost;
    }

    public String getProductName() {
        return productName;
    }

    public String getProviderName() {
        return providerName;
    }

    public double getPurchasedUnitCount() {
        return purchasedUnitCount;
    }

    public UnitConversion getUnitConversion() {
        return unitConversion;
    }

    public double getBaseItemPrice() {
        return baseItemPrice;
    }

    public double getShippingFees() {
        return shippingFees;
    }

    public double getStoreDeliveryFees() {
        return storeDeliveryFees;
    }

    public double getRawSortingLaborCost() {
        return rawSortingLaborCost;
    }

    public double getPackagingMaterialCost() {
        return packagingMaterialCost;
    }

    public List<SpoilageEntry> getSpoilageEntries() {
        return Collections.unmodifiableList(spoilageEntries);
    }

    public double getInitialWeightKg() {
        return unitConversion.toKilograms(purchasedUnitCount);
    }

    public double getTotalLandedCost() {
        return LandedCostCalculator.calculateTotalLandedCost(this);
    }

    public double getTotalSpoilageWeightKg() {
        double totalSpoilageKg = 0;
        for (SpoilageEntry entry : spoilageEntries) {
            totalSpoilageKg += entry.getLostWeightKg();
        }
        return totalSpoilageKg;
    }

    public double getRemainingSellableWeightKg() {
        return Math.max(0, getInitialWeightKg() - getTotalSpoilageWeightKg());
    }

    public boolean hasSellableInventory() {
        return getRemainingSellableWeightKg() > 0;
    }

    public double getTrueCostPerKilo() {
        return TrueCostPerKiloEngine.calculate(getTotalLandedCost(), getRemainingSellableWeightKg());
    }

    public void logSpoilage(double lostWeightKg, String reason) {
        logSpoilage(new SpoilageEntry(lostWeightKg, reason));
    }

    public void logSpoilage(SpoilageEntry entry) {
        if (entry == null) {
            throw new IllegalArgumentException("entry cannot be null.");
        }
        double projectedSpoilage = getTotalSpoilageWeightKg() + entry.getLostWeightKg();
        if (projectedSpoilage > getInitialWeightKg()) {
            throw new IllegalArgumentException("Total spoilage cannot exceed the batch weight.");
        }
        spoilageEntries.add(entry);
    }

    public double getInitialCostPerKilo() {
        return TrueCostPerKiloEngine.calculate(getTotalLandedCost(), getInitialWeightKg());
    }

    private static void validateNonNegative(double value, String fieldName) {
        if (value < 0) {
            throw new IllegalArgumentException(fieldName + " cannot be negative.");
        }
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

package com.example.kilgi.inventory.model;

import com.example.kilgi.inventory.engine.LandedCostCalculator;
import com.example.kilgi.inventory.engine.TrueCostPerKiloEngine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Core domain model for a vegetable procurement batch.
 */
public class ProcurementBatch {

    private final String productName;
    private final String providerName;
    private final MeasuredWholesaleUnits measuredWholesaleUnits;
    private final UnitConversion unitConversion;
    private final double baseItemPrice;
    private final double shippingFees;
    private final double storeDeliveryFees;
    private final double rawSortingLaborCost;
    private final double packagingMaterialCost;
    private final List<SpoilageEntry> spoilageEntries = new ArrayList<>();

    public ProcurementBatch(
            String productName,
            String providerName,
            MeasuredWholesaleUnits measuredWholesaleUnits,
            UnitConversion unitConversion,
            double baseItemPrice,
            double shippingFees,
            double storeDeliveryFees,
            double rawSortingLaborCost,
            double packagingMaterialCost
    ) {
        this.productName = requireText(productName, "productName");
        this.providerName = requireText(providerName, "providerName");
        if (measuredWholesaleUnits == null) {
            throw new IllegalArgumentException("measuredWholesaleUnits cannot be null.");
        }
        if (unitConversion == null) {
            throw new IllegalArgumentException("unitConversion cannot be null.");
        }
        if (!measuredWholesaleUnits.getUnitName().equalsIgnoreCase(unitConversion.getUnitName())) {
            throw new IllegalArgumentException("unitConversion unitName must match measuredWholesaleUnits unitName.");
        }
        validateNonNegative(baseItemPrice, "baseItemPrice");
        validateNonNegative(shippingFees, "shippingFees");
        validateNonNegative(storeDeliveryFees, "storeDeliveryFees");
        validateNonNegative(rawSortingLaborCost, "rawSortingLaborCost");
        validateNonNegative(packagingMaterialCost, "packagingMaterialCost");

        this.measuredWholesaleUnits = measuredWholesaleUnits;
        this.unitConversion = unitConversion;
        this.baseItemPrice = baseItemPrice;
        this.shippingFees = shippingFees;
        this.storeDeliveryFees = storeDeliveryFees;
        this.rawSortingLaborCost = rawSortingLaborCost;
        this.packagingMaterialCost = packagingMaterialCost;
    }

    public String getProductName() {
        return productName;
    }

    public String getProviderName() {
        return providerName;
    }

    public int getPurchasedUnitCount() {
        return measuredWholesaleUnits.getUnitCount();
    }

    public MeasuredWholesaleUnits getMeasuredWholesaleUnits() {
        return measuredWholesaleUnits;
    }

    public UnitConversion getUnitConversion() {
        return unitConversion;
    }

    public double getBaseItemPrice() {
        return baseItemPrice;
    }

    public double getShippingFees() {
        return shippingFees;
    }

    public double getStoreDeliveryFees() {
        return storeDeliveryFees;
    }

    public double getRawSortingLaborCost() {
        return rawSortingLaborCost;
    }

    public double getPackagingMaterialCost() {
        return packagingMaterialCost;
    }

    public List<SpoilageEntry> getSpoilageEntries() {
        return Collections.unmodifiableList(spoilageEntries);
    }

    public List<Double> getPurchasedUnitWeightsKg() {
        return measuredWholesaleUnits.getUnitWeightsKg();
    }

    public double getInitialWeightKg() {
        return unitConversion.toKilograms(measuredWholesaleUnits.getUnitWeightsKg());
    }

    public double getAverageUnitWeightKg() {
        return unitConversion.getAverageKilogramsPerUnit(measuredWholesaleUnits.getUnitWeightsKg());
    }

    public double getTotalLandedCost() {
        return LandedCostCalculator.calculateTotalLandedCost(this);
    }

    public double getTotalSpoilageWeightKg() {
        double totalSpoilageKg = 0;
        for (SpoilageEntry entry : spoilageEntries) {
            totalSpoilageKg += entry.getLostWeightKg();
        }
        return totalSpoilageKg;
    }

    public double getRemainingSellableWeightKg() {
        return Math.max(0, getInitialWeightKg() - getTotalSpoilageWeightKg());
    }

    public boolean hasSellableInventory() {
        return getRemainingSellableWeightKg() > 0;
    }

    public double getTrueCostPerKilo() {
        return TrueCostPerKiloEngine.calculate(getTotalLandedCost(), getRemainingSellableWeightKg());
    }

    public void logSpoilage(double lostWeightKg, String reason) {
        logSpoilage(new SpoilageEntry(lostWeightKg, reason));
    }

    public void logSpoilage(SpoilageEntry entry) {
        if (entry == null) {
            throw new IllegalArgumentException("entry cannot be null.");
        }
        double projectedSpoilage = getTotalSpoilageWeightKg() + entry.getLostWeightKg();
        if (projectedSpoilage > getInitialWeightKg()) {
            throw new IllegalArgumentException("Total spoilage cannot exceed the batch weight.");
        }
        spoilageEntries.add(entry);
    }

    public double getInitialCostPerKilo() {
        return TrueCostPerKiloEngine.calculate(getTotalLandedCost(), getInitialWeightKg());
    }

    private static void validateNonNegative(double value, String fieldName) {
        if (value < 0) {
            throw new IllegalArgumentException(fieldName + " cannot be negative.");
        }
    }

    private static String requireText(String value, String fieldName) {
        if (value == null || value.trim().isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be blank.");
        }
        return value.trim();
    }
}

package com.example.kilgi.inventory.model;

import com.example.kilgi.inventory.engine.LandedCostCalculator;
import com.example.kilgi.inventory.engine.TrueCostPerKiloEngine;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class ProcurementBatchTest {

    @Test
    public void landedCost_sumsEveryProcurementCost() {
        double landedCost = LandedCostCalculator.calculateTotalLandedCost(5000, 300, 200, 150, 50);

        assertEquals(5700, landedCost, 0.0001);
    }

    @Test
    public void batch_calculatesInitialAndTrueCostPerKilo() {
        ProcurementBatch batch = createTomatoBatch();

        assertEquals(100, batch.getInitialWeightKg(), 0.0001);
        assertEquals(57, batch.getInitialCostPerKilo(), 0.0001);

        batch.logSpoilage(10, "Rotten tomatoes");

        assertEquals(10, batch.getTotalSpoilageWeightKg(), 0.0001);
        assertEquals(90, batch.getRemainingSellableWeightKg(), 0.0001);
        assertEquals(63.3333, batch.getTrueCostPerKilo(), 0.0001);
    }

    @Test
    public void batch_supportsMultipleSpoilageLogs() {
        ProcurementBatch batch = createTomatoBatch();

        batch.logSpoilage(5, "Bruised during unloading");
        batch.logSpoilage(new SpoilageEntry(7.5, "Overripe produce", 1720195200000L));

        assertEquals(12.5, batch.getTotalSpoilageWeightKg(), 0.0001);
        assertEquals(87.5, batch.getRemainingSellableWeightKg(), 0.0001);
        assertEquals(65.142857, batch.getTrueCostPerKilo(), 0.0001);
        assertEquals(2, batch.getSpoilageEntries().size());
    }

    @Test
    public void batch_rejectsSpoilageThatExceedsInventory() {
        ProcurementBatch batch = createTomatoBatch();

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> batch.logSpoilage(101, "Everything spoiled")
        );

        assertTrue(exception.getMessage().contains("cannot exceed"));
    }

    @Test
    public void trueCostEngine_requiresSellableWeight() {
        IllegalStateException exception = assertThrows(
                IllegalStateException.class,
                () -> TrueCostPerKiloEngine.calculate(5700, 0)
        );

        assertTrue(exception.getMessage().contains("greater than zero"));
    }

    @Test
    public void unitConversion_translatesWholesaleUnitsToKilograms() {
        UnitConversion unitConversion = new UnitConversion("crate", 22.5);

        assertEquals(67.5, unitConversion.toKilograms(3), 0.0001);
        assertEquals(1.333333, unitConversion.toUnits(30), 0.0001);
    }

    private ProcurementBatch createTomatoBatch() {
        return new ProcurementBatch(
                "Tomato",
                "Davao Growers Cooperative",
                4,
                new UnitConversion("sack", 25),
                5000,
                300,
                200,
                150,
                50
        );
    }
}

